using System;using System.IO;using System.Reflection;using System.Collections.Generic;using System.Web.Script.Serialization;
class AiCheck {
 static int count;static JavaScriptSerializer json=new JavaScriptSerializer();static void Check(bool ok,string s){if(!ok)throw new Exception(s);count++;Console.WriteLine("PASS "+s);}static string Envelope(object content,string finish="stop"){return json.Serialize(new{choices=new[]{new{message=new{content=content},finish_reason=finish}}});}static void Reject(string response,string contains){try{TV.ParseAiRows(response);}catch(Exception e){Check(e.Message.Contains(contains),"diagnostic: "+contains);return;}throw new Exception("expected parser rejection");}
 static int Main(string[] args){try{string body="[{\"id\":\"com.example.app\",\"risk\":\"low\",\"reason\":\"中文依据包含 [方括号] 和引号 \\\"内容\\\"\"}]";Check(TV.ParseAiRows(Envelope(body))[0]["reason"].Contains("中文"),"UTF8 Chinese and bracketed reason parsed");Check(TV.ParseAiRows(Envelope("```json\n"+body+"\n``` "))[0]["id"]=="com.example.app","markdown array parsed");Check(TV.ParseAiRows(Envelope("说明\n{\"suggestions\":"+body+"}\n结束" )).Count==1,"object wrapper and surrounding prose parsed");Check(TV.ParseAiRows(Envelope(new[]{new{type="text",text="{\"suggestions\":"+body+"}"}})).Count==1,"content block array parsed");Reject(Envelope("not json"),"清单");Reject(Envelope(body,"length"),"截断");Reject(Envelope((string)null),"正文");Reject("{\"error\":{\"code\":402,\"message\":\"credits\"}}","额度不足");Reject("{\"error\":{\"code\":429}}","限流");Check(TV.CanUseSharedAi("https://openrouter.ai/api/v1/chat/completions","openrouter/free"),"public fallback only matches free route");Check(!TV.CanUseSharedAi("https://evil.example/api/v1/chat/completions","openrouter/free"),"public key never sent to custom host");Check(!TV.CanUseSharedAi("https://openrouter.ai/api/v1/chat/completions","paid/model"),"public key never used for paid model");Check(TV.SelectAiKey("https://example.com","custom","personal-test")=="personal-test","personal credential has priority");Check(TV.SelectAiKey("https://openrouter.ai/api/v1/chat/completions","openrouter/free","").StartsWith("sk-or-"),"authorized public key embedded");foreach(string fixture in new[]{"openrouter-live-baseline.json","openrouter-live-structured.json"})if(File.Exists(args[0]+"/"+fixture))Check(TV.ParseAiRows(File.ReadAllText(args[0]+"/"+fixture)).Count==3,"real OpenRouter response parsed: "+fixture);
 if(args.Length>1&&args[1]=="--live"){var request=new Dictionary<string,object>{{"model","openrouter/free"},{"response_format",TV.AiSchema()},{"provider",new{require_parameters=true}},{"max_tokens",4096},{"messages",new[]{new{role="system",content="保守分析Android TV卸载风险，仅返回suggestions数组的JSON对象，每项id,risk(low/unknown/high),reason中文。系统核心和桌面必须high，未知为unknown。"},new{role="user",content="[{\"id\":\"com.android.systemui\",\"name\":\"系统界面\",\"system\":true},{\"id\":\"com.vendor.tvhome\",\"name\":\"电视桌面\",\"system\":true},{\"id\":\"com.example.game\",\"name\":\"游戏\",\"system\":false}]"}}}};var post=typeof(TV).GetMethod("PostAi",BindingFlags.Static|BindingFlags.NonPublic);string response=(string)post.Invoke(null,new object[]{"https://openrouter.ai/api/v1/chat/completions",json.Serialize(request),TV.SelectAiKey("https://openrouter.ai/api/v1/chat/completions","openrouter/free","")});var rows=TV.ParseAiRows(response);Check(rows.Count==3&&rows.Exists(x=>x["reason"].Contains("系统")||x["reason"].Contains("桌面")),"production .NET client live API and Chinese result");File.WriteAllText(args[0]+"/openrouter-live-dotnet.json",response);}
 Console.WriteLine(count+" AI checks passed; keys are not printed");return 0;}catch(Exception e){Console.Error.WriteLine(e is TargetInvocationException?e.InnerException.Message:e.Message);return 1;}}
}
